// Package render generates Backlog.md, a read-only Markdown view of the
// ticket store, and writes it atomically.
package render

import (
	"bytes"
	"fmt"
	"os"
	"path/filepath"
	"strings"

	"github.com/ProlesDei/maestro/tools/maestro-ticket/ticket"
)

// Banner is the first line of every generated file.
const Banner = "<!-- generated by maestro-ticket render, do not edit -->"

// Backlog renders tickets grouped by status in workflow order. The output
// depends only on its inputs (no wall-clock time), so re-rendering an
// unchanged store produces an identical file. lastSeq is the newest event
// seq the view reflects.
func Backlog(tickets []ticket.Ticket, lastSeq int64) []byte {
	by := map[ticket.Status][]ticket.Ticket{}
	for _, t := range tickets {
		by[t.Status] = append(by[t.Status], t)
	}
	var b bytes.Buffer
	fmt.Fprintln(&b, Banner)
	fmt.Fprintln(&b, "# Backlog")
	fmt.Fprintln(&b)
	fmt.Fprintf(&b, "Generated from the ticket store at event seq %d. Change tickets with `maestro-ticket`, then run `maestro-ticket render`.\n", lastSeq)
	fmt.Fprintln(&b)
	fmt.Fprintln(&b, "| Status | Count |")
	fmt.Fprintln(&b, "|---|---|")
	for _, st := range ticket.Statuses {
		fmt.Fprintf(&b, "| %s | %d |\n", st, len(by[st]))
	}
	for _, st := range ticket.Statuses {
		list := by[st]
		if len(list) == 0 {
			continue
		}
		fmt.Fprintln(&b)
		fmt.Fprintf(&b, "## %s\n\n", st)
		if st == ticket.StatusBacklog {
			fmt.Fprintln(&b, "| ID | P | Title | Parked | Role | Claim | Version |")
			fmt.Fprintln(&b, "|---|---|---|---|---|---|---|")
			for _, t := range list {
				fmt.Fprintf(&b, "| %s | P%d | %s | %s | %s | %s | %d |\n",
					t.ID, t.Priority, cell(t.Title), t.Parked, cell(t.Role), claimCell(t.Claim), t.Version)
			}
			continue
		}
		fmt.Fprintln(&b, "| ID | P | Title | Role | Claim | Version |")
		fmt.Fprintln(&b, "|---|---|---|---|---|---|")
		for _, t := range list {
			fmt.Fprintf(&b, "| %s | P%d | %s | %s | %s | %d |\n",
				t.ID, t.Priority, cell(t.Title), cell(t.Role), claimCell(t.Claim), t.Version)
		}
	}
	return b.Bytes()
}

func claimCell(c *ticket.Claim) string {
	if c == nil {
		return ""
	}
	if c.Expired {
		return cell(c.Holder) + " (expired)"
	}
	return cell(c.Holder) + " until " + c.ExpiresAt.Format("2006-01-02 15:04Z")
}

func cell(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "|", "\\|")
	s = strings.ReplaceAll(s, "\r", " ")
	return strings.ReplaceAll(s, "\n", " ")
}

// WriteAtomic writes data to path via a temp file in the same directory,
// fsyncs it and renames it into place, so readers see the old file or the
// new one, never a partial write.
func WriteAtomic(path string, data []byte) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	f, err := os.CreateTemp(dir, "."+filepath.Base(path)+".tmp-*")
	if err != nil {
		return err
	}
	tmp := f.Name()
	defer os.Remove(tmp) // no-op after a successful rename
	if _, err := f.Write(data); err != nil {
		f.Close()
		return err
	}
	if err := f.Sync(); err != nil {
		f.Close()
		return err
	}
	if err := f.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tmp, 0o644); err != nil {
		return err
	}
	if err := os.Rename(tmp, path); err != nil {
		return err
	}
	if d, err := os.Open(dir); err == nil {
		d.Sync()
		d.Close()
	}
	return nil
}
